{
  "name": "opencode-freepi",
  "version": "1.0.0",
  "description": "Free Pi provider connector for opencode",
  "private": true,
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.18"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "autoupdate": false,
  "plugins": ["~/.config/opencode/plugins/freepi-session.ts"],
  "tool_output": {
    "max_lines": 400,
    "max_bytes": 16384
  },
  "agent": {
    "title": {
      "model": "freepi/deepseek-v4.1-flash"
    },
    "summary": {
      "model": "freepi/deepseek-v4.1-flash"
    },
    "compaction": {
      "model": "freepi/deepseek-v4.1-flash"
    }
  },
  "model": "opencode/mimo-v2.6-flash-free",
  "small_model": "opencode/mimo-v2.6-flash-free",
  "provider": {
    "freepi": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "Free Pi",
      "options": {
        "baseURL": "https://api.freepi.ai/v1",
        "apiKey": "{file:~/.config/opencode/freepi.key}",
        "headers": {
          "x-session-id": "opencode-freepi",
          "x-client-version": "0.6.11"
        }
      },
      "models": {
        "particle": { "name": "Particle (free unlimited)", "reasoning": false, "limit": { "context": 200000, "output": 8192 } },
        "deepseek-v4.1-flash": { "name": "DeepSeek V4.1 Flash (free unlimited)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "glm-5.3-flash": { "name": "GLM 5.3 Flash (free unlimited)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "deepseek-v4-flash": { "name": "DeepSeek V4 Flash (1x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "deepseek-v4-pro": { "name": "DeepSeek V4 Pro (~18x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "claude-haiku-5.5": { "name": "Claude Haiku 5.5 (~2x)", "reasoning": false, "limit": { "context": 200000, "output": 8192 } },
        "gpt-6-luna": { "name": "GPT-6 Luna (~2x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "gpt-6-luna-flex": { "name": "GPT-6 Luna Flex (~2x, slower)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "gpt-6.1-sol-flex": { "name": "GPT-6.1 Sol Flex (~41x, slower)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "gpt-6.1-terra": { "name": "GPT-6.1 Terra (~20x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "gpt-6.1-terra-flex": { "name": "GPT-6.1 Terra Flex (~20x, slower)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "gpt-oss-120b-speed": { "name": "GPT-OSS 120B (~3x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "kimi-k3.1-pro": { "name": "Kimi K3.1 Pro (~41x, daily limit)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "mimo-v2.6-flash": { "name": "MiMo V2.6 Flash (~2.8x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "qwen3.5-35b-darkbloom": { "name": "Qwen3.5 35B Darkbloom (~2.9x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "solar-pro-4": { "name": "Solar Pro 4 (~0.6x)", "reasoning": false, "limit": { "context": 200000, "output": 8192 } },
        "muse-spark-open": { "name": "Muse Spark Open (~25x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "muse-spark-1.3-contributor": { "name": "Muse Spark 1.3 Contributor (~2x, trains on your data)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "abliterated-large-v2": { "name": "Abliterated Large V2 defense (~60x)", "reasoning": false, "limit": { "context": 200000, "output": 8192 } },
        "deepseek-v4.1-flash-abliterated": { "name": "DeepSeek V4.1 Flash Abliterated (~20x)", "reasoning": true, "limit": { "context": 200000, "output": 8192 } },
        "gemma-4-uncensored": { "name": "Gemma 4 Uncensored (~20x)", "reasoning": false, "limit": { "context": 200000, "output": 8192 } },
        "glm-4.7-flash-heretic": { "name": "GLM 4.7 Flash Heretic (~20x)", "reasoning": false, "limit": { "context": 200000, "output": 8192 } },
        "qwen3.6-plus-uncensored": { "name": "Qwen 3.6 Plus Uncensored (~20x)", "reasoning": false, "limit": { "context": 200000, "output": 8192 } },
        "uncensored-1.2": { "name": "Uncensored 1.2 (~20x)", "reasoning": false, "limit": { "context": 200000, "output": 8192 } }
      }
    }
  },
  "server": {
    "port": 4096,
    "hostname": "127.0.0.1"
  }
}
